    44|const TEMPLATE_MODES = [
    45|  'NEW_APP_FROM_SCRATCH',
    46|  'NEW_MODULE_FROM_SCRATCH',
    47|  'NEW_FEATURE',
    48|  'BUG_FIX',
    49|  'REFACTOR',
    50|  'BUSINESS_WORKFLOW',
    51|  'INVESTOR_WORKFLOW',
    52|  'CRM_WORKFLOW',
    53|] as const;
    54|
    55|type WorkerTemplateMode = (typeof TEMPLATE_MODES)[number];
    56|
    57|function normalizeTemplateMode(value: unknown): WorkerTemplateMode {
    58|  const raw = readTrimmed(value).toUpperCase();
    59|  return (TEMPLATE_MODES as readonly string[]).includes(raw) ? (raw as WorkerTemplateMode) : 'NEW_FEATURE';
    60|}
    61|
    62|function readTrimmed(value: unknown): string {
    63|  return typeof value === 'string' ? value.trim() : '';
    64|}
    65|
    66|function readBoolean(value: unknown): boolean {
    67|  return value === true || readTrimmed(value).toLowerCase() === 'true';
    68|}
    69|
    70|function readStringArray(value: unknown): string[] {
    71|  if (!Array.isArray(value)) return [];
    72|  return Array.from(new Set(value.map((item) => readTrimmed(item)).filter(Boolean))).slice(0, 25);
    73|}
    74|
    75|function normalizeRiskLevel(value: unknown): 'low' | 'medium' | 'high' {
    76|  const risk = readTrimmed(value).toLowerCase();
    77|  return risk === 'low' || risk === 'high' ? risk : 'medium';
    78|}
    79|
    80|function normalizeValidationMode(value: unknown): 'focused' | 'typecheck' {
    81|  return readTrimmed(value).toLowerCase() === 'typecheck' ? 'typecheck' : 'focused';
    82|}
    83|
    84|const EXECUTION_MODES = ['read_only', 'qa_only', 'code_change', 'deploy'] as const;
    85|type WorkerExecutionMode = (typeof EXECUTION_MODES)[number];
    86|
    87|/**
    88| * Production mutations must not fall through to the legacy executor: it can
    89| * classify an implementation request as QA-only and reuse old deploy evidence.
    90| */
    91|export function resolveWorkerExecutionMode(
    92|  value: unknown,
    93|  approvePatch: boolean,
    94|  approveGitDeploy: boolean,
    95|): WorkerExecutionMode {
    96|  if (approveGitDeploy) return 'deploy';
    97|  if (approvePatch) return 'code_change';
    98|  const requested = readTrimmed(value).toLowerCase();
    99|  if ((EXECUTION_MODES as readonly string[]).includes(requested)) {
   100|    return requested as WorkerExecutionMode;
   101|  }
   102|  return 'read_only';
   103|}
