   105|function statusForError(error: unknown): number {
   106|  const message = error instanceof Error ? error.message.toLowerCase() : '';
   107|  // Auth guard failures must return 401/403, never 500.
   108|  if (message.includes('missing bearer token') || message.includes('invalid or expired')) return 401;
   109|  if (message.includes('privileged ivx access is required') || message.includes('owner') || message.includes('auth guard failed') || message.includes('auth config failed') || message.includes('role guard failed')) return 403;
   110|  return 500;
   111|}
   112|
   113|function errorResponse(error: unknown): Response {
   114|  const message = error instanceof Error ? error.message : 'IVX senior developer worker failed.';
   115|  if (error instanceof InternalDeployAuthError) {
   116|    return ownerOnlyJson({ ok: false, marker: IVX_SENIOR_DEV_WORKER_MARKER, error: message.slice(0, 500), secretValuesReturned: false, timestamp: new Date().toISOString() }, error.status);
   117|  }
   118|  if (error instanceof IVXOwnerApprovalError) {
   119|    return ownerOnlyJson({
   120|      ok: false,
   121|      ownerOnly: true,
   122|      marker: IVX_SENIOR_DEV_WORKER_MARKER,
   123|      error: message.slice(0, 500),
   124|      ownerApproval: error.proof,
   125|      exactBlocker: error.proof.blocker ?? message.slice(0, 500),
   126|      secretValuesReturned: false,
   127|      timestamp: new Date().toISOString(),
   128|    }, error.status);
   129|  }
   130|  return ownerOnlyJson({
   131|    ok: false,
   132|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   133|    error: message.slice(0, 500),
   134|    secretValuesReturned: false,
   135|    timestamp: new Date().toISOString(),
   136|  }, statusForError(error));
   137|}
