   143|/** Dedicated worker-only endpoint that atomically validates and consumes one approval. */
   144|export async function handleInternalDeploymentAuthorizationConsumeRequest(request: Request): Promise<Response> {
   145|  try {
   146|    const authorization = await authorizeInternalDeploymentRequest(request);
   147|    return ownerOnlyJson({
