   150|      authorization: {
   151|        workerId: authorization.workerId,
   152|        approvalId: authorization.approvalId,
   153|        requestedCommitSha: authorization.requestedCommitSha,
   154|        action: authorization.action,
   155|      },
   156|      secretValuesReturned: false,
   157|      timestamp: new Date().toISOString(),
   158|    });
   159|  } catch (error) {
