   174|/** POST a new owner-approved job to the worker queue. */
   175|export async function handleSeniorDeveloperWorkerEnqueueRequest(request: Request): Promise<Response> {
   176|  try {
   177|    const signedWorkerRequest = request.headers.has('X-IVX-Deploy-Signature');
   178|    const internalAuthorization = signedWorkerRequest ? await authorizeInternalDeploymentRequest(request) : null;
   179|    const ownerAuthorization = internalAuthorization ? null : await assertIVXRegisteredOwnerBearer(request, 'senior_developer_worker_enqueue');
   180|    const approval = ownerAuthorization?.approval ?? {
   181|      ownerSessionDetected: true,
   182|      bearerAccepted: true,
   183|      ownerVerified: true,
   184|      ownerEmailMatched: true,
   185|      ownerEmailMasked: 'internal-worker',
   186|      userId: `worker:${internalAuthorization?.workerId ?? 'unknown'}`,
   187|      role: 'internal_worker',
   188|      guardMode: 'strict' as const,
   189|      allowlistConfigured: true,
   190|      action: 'senior_developer_worker_enqueue',
   191|      blocker: null,
   192|      secretValuesReturned: false as const,
   193|    };
   194|    const body = await request.json().catch((): WorkerEnqueueRequest => ({}));
   195|    const goal = readTrimmed(body.goal);
   196|    const templateMode = normalizeTemplateMode(body.templateMode);
   197|    const isSystemMode = (approval.role === 'system' && approval.guardMode === 'system_bypass') || internalAuthorization !== null;
   198|    const proposedPlan = readTrimmed(body.proposedPlan);
   199|    const filesAffected = readStringArray(body.filesAffected);
   200|    const riskLevel = normalizeRiskLevel(body.riskLevel);
   201|    const rollbackOption = readTrimmed(body.rollbackOption);
   202|    const approveGitDeploy = readBoolean(body.approveGitDeploy);
   203|    const approvePatch = readBoolean(body.approvePatch);
   204|    const executionMode = resolveWorkerExecutionMode(body.executionMode, approvePatch, approveGitDeploy);
   205|
   206|    if (!goal) {
   207|      return ownerOnlyJson({
   208|        ok: false,
   209|        marker: IVX_SENIOR_DEV_WORKER_MARKER,
   210|        error: 'A senior developer goal is required.',
   211|        ownerApproval: approval,
   212|        secretValuesReturned: false,
   213|        timestamp: new Date().toISOString(),
   214|      }, 400);
   215|    }
   216|
   217|    if (!isSystemMode && approveGitDeploy && (!proposedPlan || filesAffected.length === 0 || !rollbackOption)) {
   218|      return ownerOnlyJson({
   219|        ok: false,
   220|        marker: IVX_SENIOR_DEV_WORKER_MARKER,
   221|        error: 'Owner-approved production mutation requires a visible proposed plan, files affected, risk level, and rollback option before commit/deploy.',
   222|        exactBlocker: 'approval_contract_missing_plan_files_or_rollback',
   223|        requiredFields: ['proposedPlan', 'filesAffected', 'riskLevel', 'rollbackOption'],
   224|        ownerApproval: approval,
   225|        secretValuesReturned: false,
   226|        timestamp: new Date().toISOString(),
   227|      }, 400);
   228|    }
   229|
   230|    const ownerApprovedAction = {
