   238|        `ownerSessionDetected=${approval.ownerSessionDetected}`,
   239|        `bearerAccepted=${approval.bearerAccepted}`,
   240|        `ownerVerified=${approval.ownerVerified}`,
   241|        `role=${approval.role}`,
   242|        `guardMode=${approval.guardMode}`,
   243|        `filesAffected=${filesAffected.join(', ')}`,
